import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fauxAssistantMessage, fauxText, validateToolArguments } from "@earendil-works/pi-ai";
import { registerFauxProvider } from "@earendil-works/pi-ai/compat";
import { afterAll, afterEach, describe, expect, it, vi } from "vitest";
import { installWorkManager } from "../../shared/src/work-manager.js";
import { fauxModelBackend } from "../../../tests/helpers/faux-model.js";
import installSubagents from "../src/index.js";
import { createNestedSubagentTools } from "../src/nested-tools.js";

const temporaryDirectories: string[] = [];
const fauxProviders: Array<{ unregister(): void }> = [];
const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
const isolatedAgentDir = mkdtempSync(join(tmpdir(), "apple-pi-acc-resume-agent-"));
process.env.PI_CODING_AGENT_DIR = isolatedAgentDir;

afterEach(() => {
	for (const provider of fauxProviders.splice(0)) provider.unregister();
	for (const directory of temporaryDirectories.splice(0)) rmSync(directory, { recursive: true, force: true });
});

afterAll(() => {
	if (previousAgentDir === undefined) delete process.env.PI_CODING_AGENT_DIR;
	else process.env.PI_CODING_AGENT_DIR = previousAgentDir;
	rmSync(isolatedAgentDir, { recursive: true, force: true });
});

/** Pass arguments through Pi's real argument validator, as the agent loop does. */
function viaPi(tool: any, args: Record<string, unknown>): any {
	return validateToolArguments(tool, { type: "toolCall", id: "call", name: tool.name, arguments: args } as any);
}

const STORED = {
	inheritContext: true,
	isolated: true,
	pair: true,
	profile: "deep",
	systemPrompt: "Stored guidance.",
	runInBackground: false,
};

function nestedHarness(invocation: Record<string, unknown> = STORED) {
	const records = new Map<string, any>();
	records.set("child-1", {
		id: "child-1",
		type: "general-purpose",
		description: "owned child",
		parentAgentId: "parent-1",
		status: "completed",
		result: "FIRST",
		session: {},
		invocation: { ...invocation },
	});
	records.set("foreign-1", {
		id: "foreign-1",
		type: "general-purpose",
		description: "foreign child",
		parentAgentId: "someone-else",
		status: "completed",
		result: "FIRST",
		session: {},
		invocation: { ...invocation },
	});
	const resume = vi.fn(async (id: string, _prompt: string, _signal?: AbortSignal, options?: any) => {
		const record = records.get(id);
		if (!record) return undefined;
		if (options?.isBackground) {
			record.status = "running";
			return record;
		}
		record.status = "completed";
		record.result = "RESUMED-OK";
		return record;
	});
	const manager = {
		getRecord: (id: string) => records.get(id),
		resume,
		spawn: vi.fn(() => {
			throw new Error("spawn must not be called on resume");
		}),
		spawnAndWait: vi.fn(async () => {
			throw new Error("spawnAndWait must not be called on resume");
		}),
		steer: vi.fn(() => false),
		abort: vi.fn(() => false),
	};
	const tools = createNestedSubagentTools({
		manager: manager as any,
		pi: {} as any,
		parentAgentId: "parent-1",
		depth: 1,
		maxSubagentDepth: 3,
		allowedSubagents: "all",
		configCwd: process.cwd(),
		projectTrusted: false,
	});
	const tool = tools.find((candidate) => candidate.name === "agent") as any;
	const ctx = { model: { provider: "faux", id: "parent-model" }, modelRegistry: { find: vi.fn() } } as any;
	const run = (args: Record<string, unknown>) =>
		tool.execute(
			"nested-call",
			viaPi(tool, {
				prompt: "continue",
				description: "continue",
				subagent_type: "general-purpose",
				...args,
			}),
			undefined,
			undefined,
			ctx,
		);
	return { records, resume, run, manager, tool };
}

describe("nested agent tool resume policy", () => {
	it("reuses stored true settings when fixed settings are omitted", async () => {
		const h = nestedHarness();
		const result = await h.run({ resume: "child-1" });
		expect(result.isError).toBeFalsy();
		expect(h.resume).toHaveBeenCalledOnce();
		expect(h.resume.mock.calls[0][0]).toBe("child-1");
		expect(result.content[0].text).toContain("RESUMED-OK");
	});

	it("keeps omission distinct from explicit false through Pi's validator", () => {
		const h = nestedHarness();
		const omitted = viaPi(h.tool, { prompt: "p", description: "d", subagent_type: "x", resume: "child-1" });
		expect(omitted.inherit_context).toBeUndefined();
		expect(omitted.isolated).toBeUndefined();
		const explicit = viaPi(h.tool, {
			prompt: "p",
			description: "d",
			subagent_type: "x",
			resume: "child-1",
			inherit_context: false,
			isolated: false,
		});
		expect(explicit.inherit_context).toBe(false);
		expect(explicit.isolated).toBe(false);
	});

	it("accepts explicit matching settings", async () => {
		const h = nestedHarness();
		const result = await h.run({
			resume: "child-1",
			inherit_context: true,
			isolated: true,
			pair: true,
			profile: "deep",
			system_prompt: "Stored guidance.",
		});
		expect(result.isError).toBeFalsy();
		expect(h.resume).toHaveBeenCalledOnce();
	});

	it("treats blank guidance as omission", async () => {
		const h = nestedHarness();
		const result = await h.run({ resume: "child-1", system_prompt: "   " });
		expect(result.isError).toBeFalsy();
		expect(h.resume).toHaveBeenCalledOnce();
	});

	it.each([
		["inherit_context", { inherit_context: false }],
		["isolated", { isolated: false }],
		["pair", { pair: false }],
		["profile", { profile: "quick" }],
		["system_prompt", { system_prompt: "Different guidance." }],
	])("rejects an explicitly changed %s before resume", async (_name, change) => {
		const h = nestedHarness();
		const result = await h.run({ resume: "child-1", ...change });
		expect(result.isError).toBe(true);
		expect(h.resume).not.toHaveBeenCalled();
		expect(h.records.get("child-1").invocation).toEqual(STORED);
	});

	it.each([
		["inherit_context", { inherit_context: true }],
		["isolated", { isolated: true }],
		["pair", { pair: true }],
	])("rejects explicit true for %s when stored false", async (_name, change) => {
		const stored = { inheritContext: false, isolated: false, pair: false };
		const h = nestedHarness(stored);
		const result = await h.run({ resume: "child-1", ...change });
		expect(result.isError).toBe(true);
		expect(h.resume).not.toHaveBeenCalled();
		const ok = await h.run({ resume: "child-1", inherit_context: false, isolated: false, pair: false });
		expect(ok.isError).toBeFalsy();
		expect(h.resume).toHaveBeenCalledOnce();
	});

	it("lets foreground/background change per invocation", async () => {
		const h = nestedHarness({ ...STORED, runInBackground: false });
		const background = await h.run({ resume: "child-1", run_in_background: true });
		expect(background.isError).toBeFalsy();
		expect(h.resume).toHaveBeenCalledOnce();
		expect(h.resume.mock.calls[0][3]).toMatchObject({ isBackground: true });
		h.records.get("child-1").status = "completed";
		const foreground = await h.run({ resume: "child-1", run_in_background: false });
		expect(foreground.isError).toBeFalsy();
		expect(h.resume).toHaveBeenCalledTimes(2);
		expect(h.resume.mock.calls[1][3]?.isBackground ?? false).toBe(false);
	});

	it("keeps ownership checks", async () => {
		const h = nestedHarness();
		const result = await h.run({ resume: "foreign-1" });
		expect(result.isError).toBe(true);
		expect(h.resume).not.toHaveBeenCalled();
	});
});

function rootHarness() {
	const cwd = mkdtempSync(join(tmpdir(), "apple-pi-acc-resume-"));
	temporaryDirectories.push(cwd);
	mkdirSync(join(cwd, ".pi", "agents"), { recursive: true });
	writeFileSync(
		join(cwd, ".pi", "agents", "tool-test.md"),
		`---
name: tool-test
description: public tool test
tools: read
extensions: false
skills: false
persist_session: false
---
Answer the task.
`,
	);
	writeFileSync(join(cwd, ".pi", "subagents.json"), JSON.stringify({ maxConcurrent: 2 }));
	const faux = registerFauxProvider({ provider: "faux", models: [{ id: "faux-acc", contextWindow: 200_000 }] });
	fauxProviders.push(faux);
	let replies = 0;
	const reply = () => fauxAssistantMessage([fauxText(`REPLY-${++replies}`)]);
	faux.setResponses(Array.from({ length: 20 }, () => reply));
	const model = faux.getModel();
	const runtime = fauxModelBackend(model);
	const tools = new Map<string, any>();
	const busListeners = new Map<string, Set<(payload: unknown) => void>>();
	const pi = {
		registerMessageRenderer: () => {},
		registerTool: (tool: any) => tools.set(tool.name, tool),
		registerCommand: () => {},
		registerShortcut: () => {},
		on: () => {},
		events: {
			emit: (name: string, payload: any) => {
				for (const listener of busListeners.get(name) ?? []) listener(payload);
			},
			on: (name: string, listener: (payload: unknown) => void) => {
				const listeners = busListeners.get(name) ?? new Set();
				listeners.add(listener);
				busListeners.set(name, listeners);
				return () => listeners.delete(listener);
			},
		},
		sendMessage: () => {},
		exec: async () => ({ code: 1, stdout: "", stderr: "" }),
	} as any;
	const ctx = {
		cwd,
		model,
		modelRegistry: runtime.modelRegistry,
		getSystemPrompt: () => "parent",
		sessionManager: { getSessionFile: () => undefined, getBranch: () => [] },
		isProjectTrusted: () => true,
		hasUI: false,
	} as any;
	return { cwd, tools, pi, ctx, replies: () => replies };
}

describe("root agent tool resume policy", () => {
	it("reuses stored settings on omission, accepts matches, rejects changes", async () => {
		const h = rootHarness();
		const previousCwd = process.cwd();
		process.chdir(h.cwd);
		try {
			installWorkManager(h.pi);
			installSubagents(h.pi);
			const tool = h.tools.get("agent");
			const getResult = h.tools.get("get_subagent_result");
			const run = (id: string, args: Record<string, unknown>) =>
				tool.execute(
					id,
					viaPi(tool, { prompt: "task", description: "Resume test", subagent_type: "tool-test", ...args }),
					undefined,
					undefined,
					h.ctx,
				);

			const first = await run("start", {
				inherit_context: true,
				isolated: true,
				system_prompt: "Stored guidance.",
			});
			expect(first.isError).toBeFalsy();
			const agentId = (first.content[0].text as string).match(/Agent ID: ([^\s]+)/)?.[1];
			expect(agentId).toBeTruthy();

			// Omitted fixed settings reuse the stored true values.
			const omitted = await run("omit", { resume: agentId, prompt: "follow up" });
			expect(omitted.content[0].text).not.toContain("fixed when an agent session starts");
			expect(omitted.isError).toBeFalsy();
			const afterOmit = h.replies();
			expect(afterOmit).toBe(2);

			// Blank guidance is omission.
			const blank = await run("blank", { resume: agentId, system_prompt: "   " });
			expect(blank.isError).toBeFalsy();
			expect(h.replies()).toBe(3);

			// Explicit matching choices succeed.
			const matching = await run("match", {
				resume: agentId,
				inherit_context: true,
				isolated: true,
				system_prompt: "Stored guidance.",
			});
			expect(matching.isError).toBeFalsy();
			expect(h.replies()).toBe(4);

			// Conflicting choices fail before resume.
			for (const change of [
				{ inherit_context: false },
				{ isolated: false },
				{ pair: true },
				{ system_prompt: "Different guidance." },
				{ profile: "quick" },
			]) {
				const conflict = await run("conflict", { resume: agentId, ...change });
				expect(conflict.isError, JSON.stringify(change)).toBe(true);
				expect(h.replies()).toBe(4);
			}

			// Stored choices are unchanged after rejections: omission still works.
			const again = await run("again", { resume: agentId });
			expect(again.isError).toBeFalsy();
			expect(h.replies()).toBe(5);

			// Background is per-invocation.
			const bg = await run("bg", { resume: agentId, run_in_background: true });
			expect(bg.isError).toBeFalsy();
			expect(bg.content[0].text).toContain(agentId);
			const waited = await getResult.execute("wait", { agent_id: agentId }, undefined);
			expect(waited.isError).toBeFalsy();
			expect(h.replies()).toBe(6);

			// New-session defaults remain false; explicit true on resume is a change.
			const fresh = await run("fresh", {});
			expect(fresh.isError).toBeFalsy();
			const freshId = (fresh.content[0].text as string).match(/Agent ID: ([^\s]+)/)?.[1];
			expect(freshId).toBeTruthy();
			expect(freshId).not.toBe(agentId);
			const replies = h.replies();
			for (const change of [{ inherit_context: true }, { isolated: true }]) {
				const conflict = await run("fresh-conflict", { resume: freshId, ...change });
				expect(conflict.isError, JSON.stringify(change)).toBe(true);
			}
			expect(h.replies()).toBe(replies);
			const freshFalse = await run("fresh-false", { resume: freshId, inherit_context: false, isolated: false });
			expect(freshFalse.isError).toBeFalsy();
			const freshOmit = await run("fresh-omit", { resume: freshId });
			expect(freshOmit.isError).toBeFalsy();
			expect(h.replies()).toBe(replies + 2);
		} finally {
			process.chdir(previousCwd);
		}
	}, 60_000);
});
